{"command": "cd "$WORKSPACE_DIR" && python3 - <<'PY'
import subprocess, re, json, sys
sys.path.insert(0,'work')
from toc_data import TOC
txt = subprocess.run(['pdftotext','-layout','work/lease-abstraction-report.pdf','-'],capture_output=True,text=True).stdout
pages = txt.split('\f')
norm = lambda s: re.sub(r'\s+','',s)
out={}; missing=[]
for num,title,key in TOC:
    k=norm(key)
    hits=[i+1 for i,p in enumerate(pages) if k in norm(p)]
    if hits: out[k]=max(hits)
    else: missing.append(key)
json.dump(out, open('work/toc_pages.json','w'))
print('resolved', len(out), '/', len(TOC), 'missing:', missing)
for num,title,key in TOC[:6]: print(num, out.get(norm(key)))
print('...')
for num,title,key in TOC[-6:]: print(num, out.get(norm(key)))
PY"}

